// BaseNode.js
// Core abstraction for all pipeline nodes.
//
// Usage:
//   <BaseNode id={id} data={data} label="My Node" color="#4f46e5" inputs={[...]} outputs={[...]}>
//     {/* custom fields rendered in the body */}
//   </BaseNode>
//
// Handle descriptors (inputs / outputs arrays):
//   { id: string, label: string, position?: number }
//   - `id` becomes the ReactFlow handle id as `${nodeId}-${id}`
//   - `label` is shown as a small annotation beside the handle
//   - `position` (0–1) overrides the evenly-spaced default vertical placement

import { Handle, Position } from 'reactflow';

// ─── design tokens ────────────────────────────────────────────────────────────
const TOKENS = {
  nodeWidth: 220,
  nodeRadius: 10,
  headerHeight: 32,
  bodyPadding: '10px 12px',
  fontFamily: "'Inter', system-ui, sans-serif",
  fontSize: 12,
  labelFontSize: 10,
  inputBg: '#f8f8fa',
  inputBorder: '#d1d5db',
  inputRadius: 5,
  inputPadding: '3px 6px',
  shadowBase: '0 1px 3px rgba(0,0,0,.12), 0 1px 2px rgba(0,0,0,.08)',
  shadowHover: '0 4px 12px rgba(0,0,0,.15)',
  handleSize: 10,
  handleBorder: '2px solid white',
};

// ─── shared sub-components ────────────────────────────────────────────────────

/** Tiny label that floats next to a handle */
const HandleLabel = ({ label, side }) => (
  <span style={{
    position: 'absolute',
    fontSize: 9,
    color: '#6b7280',
    whiteSpace: 'nowrap',
    ...(side === 'left'  ? { left: 14 }  : { right: 14 }),
    transform: 'translateY(-50%)',
    pointerEvents: 'none',
    userSelect: 'none',
  }}>
    {label}
  </span>
);

/** A labelled text input */
export const NodeTextField = ({ label, value, onChange, placeholder }) => (
  <label style={{ display: 'flex', flexDirection: 'column', gap: 2, fontSize: TOKENS.fontSize }}>
    <span style={{ color: '#6b7280', fontSize: TOKENS.labelFontSize, fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.04em' }}>
      {label}
    </span>
    <input
      type="text"
      value={value}
      onChange={onChange}
      placeholder={placeholder}
      style={{
        background: TOKENS.inputBg,
        border: `1px solid ${TOKENS.inputBorder}`,
        borderRadius: TOKENS.inputRadius,
        padding: TOKENS.inputPadding,
        fontSize: TOKENS.fontSize,
        fontFamily: TOKENS.fontFamily,
        outline: 'none',
        width: '100%',
        boxSizing: 'border-box',
      }}
    />
  </label>
);

/** A labelled textarea */
export const NodeTextArea = ({ label, value, onChange, placeholder, rows = 3 }) => (
  <label style={{ display: 'flex', flexDirection: 'column', gap: 2, fontSize: TOKENS.fontSize }}>
    <span style={{ color: '#6b7280', fontSize: TOKENS.labelFontSize, fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.04em' }}>
      {label}
    </span>
    <textarea
      value={value}
      onChange={onChange}
      placeholder={placeholder}
      rows={rows}
      style={{
        background: TOKENS.inputBg,
        border: `1px solid ${TOKENS.inputBorder}`,
        borderRadius: TOKENS.inputRadius,
        padding: TOKENS.inputPadding,
        fontSize: TOKENS.fontSize,
        fontFamily: TOKENS.fontFamily,
        outline: 'none',
        resize: 'vertical',
        width: '100%',
        boxSizing: 'border-box',
      }}
    />
  </label>
);

/** A labelled select */
export const NodeSelect = ({ label, value, onChange, options }) => (
  <label style={{ display: 'flex', flexDirection: 'column', gap: 2, fontSize: TOKENS.fontSize }}>
    <span style={{ color: '#6b7280', fontSize: TOKENS.labelFontSize, fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.04em' }}>
      {label}
    </span>
    <select
      value={value}
      onChange={onChange}
      style={{
        background: TOKENS.inputBg,
        border: `1px solid ${TOKENS.inputBorder}`,
        borderRadius: TOKENS.inputRadius,
        padding: TOKENS.inputPadding,
        fontSize: TOKENS.fontSize,
        fontFamily: TOKENS.fontFamily,
        outline: 'none',
        width: '100%',
      }}
    >
      {options.map(({ value: v, label: l }) => (
        <option key={v} value={v}>{l}</option>
      ))}
    </select>
  </label>
);

/** A labelled number input */
export const NodeNumberField = ({ label, value, onChange, min, max, step }) => (
  <label style={{ display: 'flex', flexDirection: 'column', gap: 2, fontSize: TOKENS.fontSize }}>
    <span style={{ color: '#6b7280', fontSize: TOKENS.labelFontSize, fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.04em' }}>
      {label}
    </span>
    <input
      type="number"
      value={value}
      onChange={onChange}
      min={min}
      max={max}
      step={step}
      style={{
        background: TOKENS.inputBg,
        border: `1px solid ${TOKENS.inputBorder}`,
        borderRadius: TOKENS.inputRadius,
        padding: TOKENS.inputPadding,
        fontSize: TOKENS.fontSize,
        fontFamily: TOKENS.fontFamily,
        outline: 'none',
        width: '100%',
        boxSizing: 'border-box',
      }}
    />
  </label>
);

/** A labelled toggle/checkbox */
export const NodeToggle = ({ label, checked, onChange }) => (
  <label style={{ display: 'flex', alignItems: 'center', gap: 8, fontSize: TOKENS.fontSize, cursor: 'pointer' }}>
    <input
      type="checkbox"
      checked={checked}
      onChange={onChange}
      style={{ accentColor: '#4f46e5', width: 14, height: 14 }}
    />
    <span style={{ color: '#374151' }}>{label}</span>
  </label>
);

// ─── helpers ──────────────────────────────────────────────────────────────────

/** Compute evenly-spaced % positions for N handles, or use override */
const handleTop = (index, total, override) => {
  if (override !== undefined) return `${override * 100}%`;
  // space handles evenly between 20% and 80% of the node height
  if (total === 1) return '50%';
  const step = 60 / (total - 1);
  return `${20 + step * index}%`;
};

// ─── BaseNode ─────────────────────────────────────────────────────────────────

/**
 * BaseNode — the single shell every node in the pipeline shares.
 *
 * Props:
 *   id        {string}   ReactFlow node id
 *   label     {string}   Title shown in the header
 *   color     {string}   Header accent color (hex / css)
 *   icon      {string}   Optional emoji / text icon before the label
 *   inputs    {Array}    Left-side handle descriptors  [{ id, label, position? }]
 *   outputs   {Array}    Right-side handle descriptors [{ id, label, position? }]
 *   minHeight {number}   Minimum body height in px (default 60)
 *   children  {ReactNode} The node-specific controls rendered in the body
 */
export const BaseNode = ({
  id,
  label,
  color = '#4f46e5',
  icon,
  inputs = [],
  outputs = [],
  minHeight = 60,
  children,
}) => {
  // Derive a readable text colour for the header
  const headerTextColor = '#fff';

  return (
    <div
      style={{
        width: TOKENS.nodeWidth,
        borderRadius: TOKENS.nodeRadius,
        border: '1px solid #e5e7eb',
        boxShadow: TOKENS.shadowBase,
        fontFamily: TOKENS.fontFamily,
        fontSize: TOKENS.fontSize,
        background: '#fff',
        overflow: 'visible',
        transition: 'box-shadow 0.15s ease',
      }}
      onMouseEnter={e => e.currentTarget.style.boxShadow = TOKENS.shadowHover}
      onMouseLeave={e => e.currentTarget.style.boxShadow = TOKENS.shadowBase}
    >
      {/* ── header ── */}
      <div style={{
        background: color,
        borderRadius: `${TOKENS.nodeRadius}px ${TOKENS.nodeRadius}px 0 0`,
        height: TOKENS.headerHeight,
        display: 'flex',
        alignItems: 'center',
        padding: '0 12px',
        gap: 6,
      }}>
        {icon && (
          <span style={{ fontSize: 14, lineHeight: 1 }}>{icon}</span>
        )}
        <span style={{
          color: headerTextColor,
          fontWeight: 700,
          fontSize: 12,
          letterSpacing: '0.03em',
          textTransform: 'uppercase',
        }}>
          {label}
        </span>
      </div>

      {/* ── body ── */}
      <div style={{
        padding: TOKENS.bodyPadding,
        display: 'flex',
        flexDirection: 'column',
        gap: 8,
        minHeight: minHeight,
        position: 'relative',
      }}>
        {children}
      </div>

      {/* ── input handles (left side) ── */}
      {inputs.map((h, i) => (
        <div
          key={h.id}
          style={{
            position: 'absolute',
            left: 0,
            top: handleTop(i, inputs.length, h.position),
            transform: 'translateY(-50%)',
            display: 'flex',
            alignItems: 'center',
          }}
        >
          <Handle
            type="target"
            position={Position.Left}
            id={`${id}-${h.id}`}
            style={{
              width: TOKENS.handleSize,
              height: TOKENS.handleSize,
              background: color,
              border: TOKENS.handleBorder,
              left: -5,
            }}
          />
          <HandleLabel label={h.label} side="left" />
        </div>
      ))}

      {/* ── output handles (right side) ── */}
      {outputs.map((h, i) => (
        <div
          key={h.id}
          style={{
            position: 'absolute',
            right: 0,
            top: handleTop(i, outputs.length, h.position),
            transform: 'translateY(-50%)',
            display: 'flex',
            alignItems: 'center',
          }}
        >
          <Handle
            type="source"
            position={Position.Right}
            id={`${id}-${h.id}`}
            style={{
              width: TOKENS.handleSize,
              height: TOKENS.handleSize,
              background: color,
              border: TOKENS.handleBorder,
              right: -5,
            }}
          />
          <HandleLabel label={h.label} side="right" />
        </div>
      ))}
    </div>
  );
};
